import { SegmentedRadioGroup } from '@gravity-ui/uikit';

import { type AppLang, setLanguage, useTranslation } from './i18n';

// Language names are shown in their own language, so they never get translated.
const LANG_NAMES: Record<AppLang, string> = {
  en: 'English',
  ru: 'Русский',
};

export function LanguageSwitcher() {
  const { t, lang } = useTranslation('app');

  return (
    <SegmentedRadioGroup<AppLang>
      aria-label={t('language-switcher_label')}
      value={lang}
      onUpdate={setLanguage}
    >
      <SegmentedRadioGroup.Option<AppLang> value="en" content={LANG_NAMES.en} />
      <SegmentedRadioGroup.Option<AppLang> value="ru" content={LANG_NAMES.ru} />
    </SegmentedRadioGroup>
  );
}

